<?php
require_once __DIR__.'/config/auth.php';require_admin();
$map=['mascota'=>['mascotas','nombre','listademascotas.php'],'consulta'=>['consultas','motivo','historial.php'],'vacuna'=>['vacunas','nombre_vacuna','controlvacunas.php'],'ingreso'=>['ingresos_diarios','descripcion','movimientos.php?tipo=ingreso'],'egreso'=>['egresos','descripcion','movimientos.php?tipo=egreso']];
$type=$_GET['tipo']??'';$id=(int)($_GET['id']??0);if(!isset($map[$type])||$id<1)av_fail('Registro no válido.');
[$table,$label,$back]=$map[$type];$db=getDBConnection();$q=$db->prepare("SELECT * FROM `$table` WHERE id=?");$q->execute([$id]);$row=$q->fetch();if(!$row)av_fail('El registro ya no existe.',404);$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 $reason=trim($_POST['motivo']??'');if(!$reason||mb_strlen($reason)>500)throw new RuntimeException('Indique un motivo de hasta 500 caracteres.');
 $db->beginTransaction();$q=$db->prepare("SELECT * FROM `$table` WHERE id=? FOR UPDATE");$q->execute([$id]);$row=$q->fetch();if(!$row)throw new RuntimeException('El registro ya fue eliminado.');
 if($type==='mascota')foreach(['citas','consultas','vacunas','cortes_peluqueria'] as $dep){$q=$db->prepare("SELECT COUNT(*) FROM `$dep` WHERE mascota_id=?");$q->execute([$id]);if($q->fetchColumn())throw new RuntimeException('La mascota tiene historial clínico o citas. Conserve ese historial antes de eliminarla.');}
 $db->prepare('INSERT INTO auditoria_eliminaciones(tabla,registro_id,datos,motivo,usuario_id) VALUES(?,?,?,?,?)')->execute([$table,$id,json_encode($row,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$reason,auth_user_id()]);
 $db->prepare("DELETE FROM `$table` WHERE id=?")->execute([$id]);$db->commit();header('Location: '.$back);exit;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('[eliminar] '.$e->getMessage());$error=$e instanceof PDOException?'No se pudo eliminar: hay información relacionada.':$e->getMessage();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eliminar registro</title><?php av_head();?></head><body><?php include __DIR__.'/sidebar.php';?><main class="av-page"><div class="av-card"><h1>Confirmar eliminación</h1><p><?=e(ucfirst($type))?> #<?=$id?>: <?=e($row[$label]??$row['motivo']??$row['nombre']??'Registro seleccionado')?></p><p>La eliminación conserva una copia en el registro de auditoría.</p><?php if($error):?><p class="av-error"><?=e($error)?></p><?php endif;?><form method="post"><?=av_csrf_field()?><label for="motivo">Motivo obligatorio</label><textarea id="motivo" name="motivo" required maxlength="500"></textarea><p><button>Eliminar registro</button> <a href="<?=e($back)?>">Cancelar</a></p></form></div></main></body></html>
